definition.script:
pipeline {
  agent any
  parameters {
    choice(name: 'ENVIRONMENT', choices: ['dev', 'staging', 'prod'], description: 'Where to deploy')
    string(name: 'GREETING', defaultValue: 'Hello', description: 'A word to print')
    booleanParam(name: 'RUN_TESTS', defaultValue: true, description: 'Run the test stage?')
  }
  stages {
    stage('Build') {
      steps { echo "${params.GREETING} - building for ${params.ENVIRONMENT}" }
    }
    stage('Test') {
      when { expression { return params.RUN_TESTS } }
      steps { echo 'Running tests...' }
    }
    stage('Approve prod') {
      when { expression { params.ENVIRONMENT == 'prod' } }
      steps {
        timeout(time: 5, unit: 'MINUTES') {
          input message: 'Deploy to PROD?', ok: 'Ship it'
        }
      }
    }
    stage('Deploy') {
      steps { echo "Deploying to ${params.ENVIRONMENT}" }
    }
  }
}
